#pragma once
#include <Arduino.h>
#include <LovyanGFX.hpp>
#include "network_manager.h"
#include "settings.h"
#include "storage_manager.h"
#include "atmega328p_isp.h"
#include "board_config.h"

namespace tului {
enum class UiState:uint8_t{MAIN,MCU_READER,UTILITY,SYSTEM_INFO,DISPLAY_SCREEN,NETWORK,STORAGE,ENGINEERING,ABOUT,WIFI_SCAN,KEYBOARD,FORMAT_CONFIRM,TOUCH_TEST,SD_TEST,GPIO_TEST};
enum class Icon:uint8_t{NONE,CHIP,GEAR,INFO,UI_DISPLAY,WIFI,SD,TOOLS,TOUCH,GPIO,SEARCH,BLE,BACK};
static UiState state=UiState::MAIN;
static bool uiDirty=true,touchWasDown=false,kbShift=true,kbPassword=false;
static String kbValue,selectedSsid,testMessage;
static uint8_t signature[3]={0}; static bool signatureOk=false,flashOk=false;
static bool hit(uint16_t x,uint16_t y,int a,int b,int w,int h){return x>=a&&x<a+w&&y>=b&&y<b+h;}
static void gotoState(UiState s){if(state!=s){state=s;uiDirty=true;}}
template<class D>static void header(D&d,const char*t){d.fillScreen(TFT_BLACK);d.setTextSize(2);d.setTextColor(TFT_CYAN);d.setCursor(18,12);d.print(t);d.drawFastHLine(18,36,444,0x03EF);}
template<class D>static void drawIcon(D&d,int x,int y,Icon i){d.setTextColor(TFT_WHITE);switch(i){case Icon::CHIP:d.drawRect(x-10,y-10,20,20,TFT_WHITE);d.drawRect(x-4,y-4,8,8,TFT_WHITE);break;case Icon::GEAR:d.drawCircle(x,y,11,TFT_WHITE);d.drawCircle(x,y,4,TFT_WHITE);break;case Icon::INFO:d.drawCircle(x,y,13,TFT_WHITE);d.setCursor(x-3,y-10);d.print("i");break;case Icon::UI_DISPLAY:d.drawRoundRect(x-15,y-10,30,20,3,TFT_WHITE);break;case Icon::WIFI:d.drawCircle(x,y+4,3,TFT_WHITE);d.drawArc(x,y+6,10,10,220,320,TFT_WHITE);d.drawArc(x,y+6,17,17,220,320,TFT_WHITE);break;case Icon::SD:d.drawRoundRect(x-13,y-15,26,30,3,TFT_WHITE);break;case Icon::TOOLS:d.drawLine(x-12,y-12,x+12,y+12,TFT_WHITE);d.drawLine(x+12,y-12,x-12,y+12,TFT_WHITE);break;case Icon::TOUCH:d.drawCircle(x,y-4,5,TFT_WHITE);d.drawFastVLine(x,y+1,13,TFT_WHITE);break;case Icon::GPIO:d.drawRect(x-12,y-10,24,20,TFT_WHITE);break;case Icon::SEARCH:d.drawCircle(x-3,y-3,10,TFT_WHITE);d.drawLine(x+5,y+5,x+14,y+14,TFT_WHITE);break;case Icon::BLE:d.drawLine(x,y-15,x,y+15,TFT_WHITE);d.drawLine(x,y-15,x+9,y-6,TFT_WHITE);d.drawLine(x+9,y-6,x-7,y+8,TFT_WHITE);break;case Icon::BACK:d.drawLine(x+10,y,x-10,y,TFT_WHITE);d.drawLine(x-10,y,x-2,y-8,TFT_WHITE);d.drawLine(x-10,y,x-2,y+8,TFT_WHITE);break;default:break;}}
template<class D>static void button(D&d,int x,int y,int w,int h,const char*t,uint16_t c,Icon i=Icon::NONE){d.fillRoundRect(x,y,w,h,7,c);d.drawRoundRect(x,y,w,h,7,TFT_WHITE);d.setTextColor(TFT_WHITE);d.setTextSize(2);if(i!=Icon::NONE){drawIcon(d,x+24,y+h/2,i);d.setCursor(x+45,y+(h-16)/2);}else d.setCursor(x+10,y+(h-16)/2);d.print(t);}
template<class D>static bool touchPressed(D&d,uint16_t&x,uint16_t&y){uint16_t a,b;bool down=d.getTouch(&a,&b),edge=down&&!touchWasDown;touchWasDown=down;if(!edge)return false;x=a;y=b;return true;}
template<class D>static void drawMain(D&d){header(d,"TUL MCU FIRMWARE READER");button(d,35,70,190,70,"MCU READER",0x03EF,Icon::CHIP);button(d,255,70,190,70,"UTILITY",0x801F,Icon::TOOLS);button(d,35,165,190,70,"ENGINEERING",0xFD20,Icon::GEAR);button(d,255,165,190,70,"SYSTEM INFO",0x05FF,Icon::INFO);d.setTextColor(TFT_GREEN);d.setCursor(35,250);d.print("SD READY");}
template<class D>static void drawMcu(D&d){header(d,"MCU READER");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,55);d.print("Target: ATmega328P (manual)");d.setCursor(18,82);d.print("No automatic CPU scan at boot");d.setTextColor(signatureOk?TFT_GREEN:TFT_YELLOW);d.setCursor(18,109);d.printf("Signature: %02X %02X %02X",signature[0],signature[1],signature[2]);button(d,18,140,205,55,"READ SIGNATURE",0x03EF,Icon::SEARCH);button(d,235,140,205,55,"READ FLASH -> SD",0x07E0,Icon::SD);d.setTextColor(flashOk?TFT_GREEN:TFT_WHITE);d.setCursor(18,215);d.print(flashOk?"FLASH SAVED TO SD":"READY");button(d,330,260,120,45,"BACK",0xF800,Icon::BACK);}
template<class D>static void drawUtility(D&d){header(d,"TUL UTILITY");button(d,18,55,135,48,"DISPLAY",0x801F,Icon::UI_DISPLAY);button(d,165,55,135,48,"NETWORK",0x03EF,Icon::WIFI);button(d,312,55,135,48,"STORAGE",0x07E0,Icon::SD);button(d,18,120,135,48,"ABOUT TUL",0x05FF,Icon::INFO);button(d,330,260,120,45,"BACK",0xF800,Icon::BACK);}
template<class D>static void drawInfo(D&d){header(d,"SYSTEM INFO");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,52);d.print("CPU       ESP32-S3");d.setCursor(18,76);d.printf("RAM FREE  %lu KB",ESP.getFreeHeap()/1024UL);d.setCursor(18,100);d.printf("PSRAM     %lu / %lu KB",ESP.getFreePsram()/1024UL,ESP.getPsramSize()/1024UL);d.setCursor(18,124);d.printf("FLASH     %lu MB",ESP.getFlashChipSize()/(1024UL*1024UL));d.setCursor(18,148);d.printf("SD CARD   %llu MB",storageCapacityBytes()/(1024ULL*1024ULL));d.setCursor(18,172);d.printf("SD FREE   %llu MB",storageFreeBytes()/(1024ULL*1024ULL));d.setCursor(18,196);d.printf("WiFi      %.25s",networkSSID());d.setCursor(18,220);d.printf("IP        %s",networkIP());d.setCursor(18,244);d.printf("RSSI      %d dBm",networkRSSI());button(d,330,260,120,45,"BACK",0xF800,Icon::BACK);}
template<class D>static void drawDisplay(D&d){header(d,"DISPLAY");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,55);d.printf("Brightness: %u",settings().brightness);button(d,20,82,100,42,"-",0xF800);button(d,135,82,100,42,"+",0x07E0);button(d,250,82,100,42,"100%",0x05FF);d.setCursor(18,145);d.printf("Screensaver: %u sec",settings().screensaverSeconds);button(d,20,172,100,42,"1 MIN",0x2D7F);button(d,135,172,100,42,"5 MIN",0x801F);button(d,250,172,100,42,"OFF",0xF800);button(d,330,260,120,45,"BACK",0xF800,Icon::BACK);}
template<class D>static void drawStorage(D&d){header(d,"STORAGE");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,55);d.printf("Capacity: %llu MB",storageCapacityBytes()/(1024ULL*1024ULL));d.setCursor(18,79);d.printf("Free: %llu MB",storageFreeBytes()/(1024ULL*1024ULL));button(d,18,112,200,48,"FORMAT SD",0xF800);button(d,235,112,200,48,"REFRESH",0x07E0,Icon::SD);button(d,330,260,120,45,"BACK",0xF800,Icon::BACK);}
template<class D>static void drawNetwork(D&d){header(d,"NETWORK");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,52);d.printf("WiFi: %s",settings().wifiEnabled?"ON":"OFF");d.setCursor(18,76);d.printf("SSID: %.25s",networkSSID());d.setCursor(18,100);d.printf("IP: %s",networkIP());button(d,18,125,130,44,"WIFI",0x03EF,Icon::WIFI);button(d,160,125,130,44,"SCAN",0x07E0,Icon::SEARCH);button(d,302,125,130,44,"BLE",0x801F,Icon::BLE);button(d,18,185,130,44,"KEYBOARD",0xFD20);button(d,160,185,130,44,"SAVED",0x05FF,Icon::SD);d.setTextColor(TFT_YELLOW);d.setCursor(302,200);d.print(settings().bleEnabled?"BLE ON":"BLE OFF");button(d,330,260,120,45,"BACK",0xF800,Icon::BACK);}
template<class D>static void drawEngineering(D&d){header(d,"ENGINEERING MODE");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,55);d.printf("RAM %lu KB free",ESP.getFreeHeap()/1024UL);d.setCursor(18,79);d.printf("PSRAM %lu KB free",ESP.getFreePsram()/1024UL);d.setCursor(18,103);d.printf("SD %s",storageCapacityBytes()?"READY":"FAIL");button(d,18,185,130,44,"TOUCH",0x801F,Icon::TOUCH);button(d,160,185,130,44,"SD TEST",0x07E0,Icon::SD);button(d,302,185,130,44,"GPIO",0x03EF,Icon::GPIO);button(d,330,260,120,45,"BACK",0xF800,Icon::BACK);}
template<class D>static void drawTest(D&d,const char*t){header(d,t);d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,60);d.print(testMessage.length()?testMessage:"READY");if(state==UiState::TOUCH_TEST){d.drawRect(18,100,420,110,TFT_CYAN);d.setCursor(30,120);d.print("Touch inside this box");}else if(state==UiState::GPIO_TEST){d.setCursor(18,105);d.printf("MOSI GPIO %u",PIN_ISP_MOSI);d.setCursor(18,130);d.printf("MISO GPIO %u",PIN_ISP_MISO);d.setCursor(18,155);d.printf("SCK GPIO %u",PIN_ISP_SCK);d.setCursor(18,180);d.printf("RESET GPIO %u",PIN_TARGET_RESET);}button(d,330,260,120,45,"BACK",0xF800,Icon::BACK);}
template<class D>static void drawScan(D&d){header(d,"WIFI SCAN");int n=networkScanCount();d.setTextColor(n==NETWORK_SCAN_RUNNING?TFT_YELLOW:TFT_WHITE);d.setCursor(18,52);if(n==NETWORK_SCAN_RUNNING)d.print("SCANNING...");else d.printf("Found: %d",n<0?0:n);if(n>0)for(int i=0;i<n&&i<7;i++){d.setCursor(18,78+i*25);d.printf("%d %-21s %d",i+1,networkScanName(i).c_str(),networkScanRSSI(i));}button(d,330,260,120,45,"BACK",0xF800,Icon::BACK);}
template<class D>static void drawAbout(D&d){header(d,"ABOUT TUL");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,65);d.print("TUL MCU Firmware Reader");d.setCursor(18,95);d.print("Standalone Service Instrument");button(d,330,260,120,45,"BACK",0xF800,Icon::BACK);}
template<class D>static void drawFormat(D&d){header(d,"FORMAT SD");d.setTextColor(TFT_RED);d.setCursor(25,65);d.print("ALL DATA WILL BE ERASED");button(d,25,140,190,55,"CANCEL",0xFD20);button(d,245,140,190,55,"FORMAT",0xF800);}
template<class D>static void drawKeyboard(D&d){header(d,kbPassword?"WIFI PASSWORD":"WIFI SSID");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(12,42);if(kbPassword)for(size_t i=0;i<kbValue.length();++i)d.print('*');else d.print(kbValue);const char*lo="qwertyuiopasdfghjklzxcvbnm";const char*up="QWERTYUIOPASDFGHJKLZXCVBNM";for(int i=0;i<26;i++){int r=i/10,c=i%10,x=8+c*46,y=70+r*38;d.fillRoundRect(x,y,40,32,5,(i&1)?0x2D7F:0x801F);d.setCursor(x+13,y+8);d.print(kbShift?up[i]:lo[i]);}for(int i=0;i<10;i++){int x=8+i*46;d.fillRoundRect(x,188,40,32,5,0x2945);d.setCursor(x+13,196);d.print(i==9?'0':char('1'+i));}button(d,8,230,62,40,"ESC",0xF800);button(d,76,230,64,40,"SHIFT",0xFFE0);button(d,146,230,130,40,"SPACE",0x2945);button(d,282,230,46,40,".",0x4208);button(d,334,230,54,40,"BKSP",0xF800);button(d,394,230,78,40,"ENTER",0x07E0);}
template<class D>static void drawCurrent(D&d){switch(state){case UiState::MAIN:drawMain(d);break;case UiState::MCU_READER:drawMcu(d);break;case UiState::UTILITY:drawUtility(d);break;case UiState::SYSTEM_INFO:drawInfo(d);break;case UiState::DISPLAY_SCREEN:drawDisplay(d);break;case UiState::NETWORK:drawNetwork(d);break;case UiState::STORAGE:drawStorage(d);break;case UiState::ENGINEERING:drawEngineering(d);break;case UiState::ABOUT:drawAbout(d);break;case UiState::WIFI_SCAN:drawScan(d);break;case UiState::KEYBOARD:drawKeyboard(d);break;case UiState::FORMAT_CONFIRM:drawFormat(d);break;case UiState::TOUCH_TEST:drawTest(d,"TOUCH TEST");break;case UiState::SD_TEST:drawTest(d,"SD CARD TEST");break;case UiState::GPIO_TEST:drawTest(d,"GPIO TEST");break;}uiDirty=false;}
static void startKeyboard(bool password,const String&initial=String()){kbPassword=password;kbShift=true;kbValue=initial;kbValue.reserve(64);gotoState(UiState::KEYBOARD);}
template<class D>static void handleKeyboard(D&,uint16_t x,uint16_t y){if(y>=70&&y<184){int i=((y-70)/38)*10+x/46;if(i<26&&kbValue.length()<63){const char*lo="qwertyuiopasdfghjklzxcvbnm";const char*up="QWERTYUIOPASDFGHJKLZXCVBNM";kbValue+=kbShift?up[i]:lo[i];}}else if(y>=188&&y<222){int n=x/46;if(kbValue.length()<63)kbValue+=n==9?'0':char('1'+n);}else if(y>=230){if(x<72)gotoState(UiState::NETWORK);else if(x<144)kbShift=!kbShift;else if(x<280){if(kbValue.length()<63)kbValue+=' ';}else if(x<334){if(kbValue.length()<63)kbValue+='.';}else if(x<394){if(kbValue.length())kbValue.remove(kbValue.length()-1);}else if(!kbPassword){selectedSsid=kbValue;startKeyboard(true);}else{networkSaveCredentials(selectedSsid,kbValue);networkConnectSaved();gotoState(UiState::NETWORK);}}uiDirty=true;}
template<class D>static void handlePressed(D&d,uint16_t x,uint16_t y){switch(state){case UiState::MAIN:if(hit(x,y,35,70,190,70))gotoState(UiState::MCU_READER);else if(hit(x,y,255,70,190,70))gotoState(UiState::UTILITY);else if(hit(x,y,35,165,190,70))gotoState(UiState::ENGINEERING);else if(hit(x,y,255,165,190,70))gotoState(UiState::SYSTEM_INFO);break;case UiState::MCU_READER:if(hit(x,y,18,140,205,55)){Atmega328pIsp i;i.begin();signatureOk=i.readSignature(signature);uiDirty=true;}else if(hit(x,y,235,140,205,55)){d.fillScreen(TFT_BLACK);d.setTextColor(TFT_YELLOW);d.setCursor(20,120);d.print("READING FLASH TO SD...");Atmega328pIsp i;i.begin();flashOk=i.readFlashToSd("/ATmega328P_flash.bin");uiDirty=true;}else if(hit(x,y,330,260,120,45))gotoState(UiState::MAIN);break;case UiState::UTILITY:if(hit(x,y,18,55,135,48))gotoState(UiState::DISPLAY_SCREEN);else if(hit(x,y,165,55,135,48))gotoState(UiState::NETWORK);else if(hit(x,y,312,55,135,48))gotoState(UiState::STORAGE);else if(hit(x,y,18,120,135,48))gotoState(UiState::ABOUT);else if(hit(x,y,330,260,120,45))gotoState(UiState::MAIN);break;case UiState::SYSTEM_INFO:if(hit(x,y,330,260,120,45))gotoState(UiState::MAIN);break;case UiState::DISPLAY_SCREEN:if(hit(x,y,20,82,100,42)){settings().brightness=settings().brightness>20?settings().brightness-20:0;analogWrite(45,settings().brightness);settingsSave();uiDirty=true;}else if(hit(x,y,135,82,100,42)){settings().brightness=settings().brightness<235?settings().brightness+20:255;analogWrite(45,settings().brightness);settingsSave();uiDirty=true;}else if(hit(x,y,250,82,100,42)){settings().brightness=255;analogWrite(45,255);settingsSave();uiDirty=true;}else if(hit(x,y,330,260,120,45))gotoState(UiState::UTILITY);break;case UiState::STORAGE:if(hit(x,y,18,112,200,48))gotoState(UiState::FORMAT_CONFIRM);else if(hit(x,y,235,112,200,48)){storageBegin();uiDirty=true;}else if(hit(x,y,330,260,120,45))gotoState(UiState::UTILITY);break;case UiState::FORMAT_CONFIRM:if(hit(x,y,25,140,190,55))gotoState(UiState::STORAGE);else if(hit(x,y,245,140,190,55)){storageFormat();gotoState(UiState::STORAGE);}break;case UiState::NETWORK:if(hit(x,y,18,125,130,44))networkToggleWiFi();else if(hit(x,y,160,125,130,44)){gotoState(UiState::WIFI_SCAN);networkScanWiFi();}else if(hit(x,y,302,125,130,44))networkToggleBLE();else if(hit(x,y,18,185,130,44))startKeyboard(false);else if(hit(x,y,160,185,130,44))networkConnectSaved();else if(hit(x,y,330,260,120,45))gotoState(UiState::UTILITY);break;case UiState::WIFI_SCAN:if(hit(x,y,330,260,120,45))gotoState(UiState::NETWORK);else{int n=networkScanCount();for(int i=0;i<n&&i<7;i++)if(hit(x,y,10,70+i*25,450,25)){selectedSsid=networkScanName(i);startKeyboard(true);break;}}break;case UiState::ENGINEERING:if(hit(x,y,18,185,130,44)){testMessage="Touch test ACTIVE";gotoState(UiState::TOUCH_TEST);}else if(hit(x,y,160,185,130,44)){testMessage=storageCapacityBytes()?"SD TEST: CARD READY":"SD TEST: NO CARD";gotoState(UiState::SD_TEST);}else if(hit(x,y,302,185,130,44)){testMessage="GPIO TEST: ISP PINS READY";gotoState(UiState::GPIO_TEST);}else if(hit(x,y,330,260,120,45))gotoState(UiState::MAIN);break;case UiState::TOUCH_TEST:case UiState::SD_TEST:case UiState::GPIO_TEST:if(hit(x,y,330,260,120,45))gotoState(UiState::ENGINEERING);break;case UiState::ABOUT:if(hit(x,y,330,260,120,45))gotoState(UiState::UTILITY);break;case UiState::KEYBOARD:handleKeyboard(d,x,y);break;}}
template<class D>void mainMenu(D&d){state=UiState::MAIN;touchWasDown=false;uiDirty=true;drawCurrent(d);}template<class D>void uiLoop(D&d){if(uiDirty)drawCurrent(d);uint16_t x=0,y=0;if(touchPressed(d,x,y))handlePressed(d,x,y);if(state==UiState::WIFI_SCAN&&networkScanCount()==NETWORK_SCAN_RUNNING){static uint32_t t=0;if(millis()-t>250){t=millis();uiDirty=true;}}}
}
